mapper.select:
SELECT page_path,
       COUNT(*)     AS view_count,
       0.0          AS percent
FROM page_view_log
WHERE visited_at >= #{startTime}
  AND visited_at <= #{endTime}
GROUP BY page_path
ORDER BY view_count DESC
LIMIT #{limit}

SELECT page_path,
       COUNT(*) AS view_count,
       0.0      AS percent
FROM page_view_log
WHERE visited_at >= #{startTime}
  AND visited_at <= #{endTime}
  AND country = #{country}
GROUP BY page_path
ORDER BY view_count DESC
LIMIT #{limit}

SELECT DATE_FORMAT(visited_at, #{format}) AS label,
       COUNT(*)                           AS view_count
FROM page_view_log
WHERE page_path = #{pagePath}
  AND visited_at >= #{startTime}
  AND visited_at <= #{endTime}
GROUP BY label
ORDER BY label ASC
